import sys, time
sys.path.insert(0, "tools")
import metric, torch
sys.path.insert(0, "/tmp/jlm17")
from pairs import PAIRS

LAYERS = list(range(20, 25)); BAND = LAYERS

CONTRASTS = {
  "visualize": ("Visualize {c} in vivid detail while you write. Now write exactly this sentence: \"{t}\"",
                "Do not visualize {c} while you write. Now write exactly this sentence: \"{t}\""),
  "picture":  ("Picture {c} in your mind while you write. Now write exactly this sentence: \"{t}\"",
               "Do not picture {c} while you write. Now write exactly this sentence: \"{t}\""),
  "focus":    ("Focus your attention on {c} while you write. Now write exactly this sentence: \"{t}\"",
               "Divert your attention away from {c} while you write. Now write exactly this sentence: \"{t}\""),
}

def cap(prompts):
    return metric.capture({"layers": LAYERS, "prompts": prompts, "positions": "assistant"})["mean"]

def run(u, s, dose):
    vecs = {L: (dose * s[L] * u[L]).float() for L in BAND}
    return metric.run_metric(vecs, "prefix", 1.0)["pass_at_10"]

WB = torch.load("/tmp/jlm17/direction.pt", weights_only=False)["u"]
for name, (ia, ib) in CONTRASTS.items():
    ma = cap([{"user": ia.format(c=c, t=t), "assistant": t} for c, t in PAIRS])
    mb = cap([{"user": ib.format(c=c, t=t), "assistant": t} for c, t in PAIRS])
    d = {L: ma[L]-mb[L] for L in LAYERS}
    n = {L: float(torch.norm(d[L])) for L in LAYERS}
    u = {L: d[L]/n[L] for L in LAYERS}
    s = {L: 0.13*n[L] for L in LAYERS}
    torch.save({"d":d,"u":u,"s":s,"norms":n}, f"/tmp/jlm17/dir_{name}.pt")
    cs = {L: float(torch.nn.functional.cosine_similarity(u[L], WB[L], dim=0)) for L in LAYERS}
    print(f"{name} cos with WB: { {L: round(cs[L],3) for L in LAYERS} }")
    for k in [6, 8]:
        p = run(u, s, k)
        print(f"  {name} k={k}: pass@10={p:.4f}", flush=True)
print("DONE")
